// SPARK's own practice policies. These weights are not CXC marking schemes.
// Every section below was allocated individually against the printed subpart cap.
// A method point and its result are separate: a wrong result does not erase sound working.
import { POA_HISTORICAL_PAPER2_ARCHIVE } from '../data/poaHistoricalPaper2';

const escape = (v) => v.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const canonical = (label) => escape(label).replace(/ /g, '\\s+');
const answer = (label, value, marks = 1, tolerance = 0.005) => ({
  label, marks, kind: 'number', match: { all: ['(?:^|\\n)\\s*'+canonical(label)+'\\s*[:=]'] }, numbers: [{ value, tolerance }],
  fullProof: `${label}: ${value}`, alternativeProof: `${label}: $${Number(value).toLocaleString('en-US')}`,
  incorrectProof: `${label}: ${value + Math.max(1, Math.abs(value) * .1)}`,
});
const method = (label, expression, marks = 1) => ({
  label: `${label} method`, marks, kind: 'calculation', match: { all: [canonical(label)] }, expressions: [expression],
  fullProof: `${label}: ${expression}`, alternativeProof: `${label}: (${expression})`, incorrectProof: `${label}: 1+1`,
});
const calc = (label, expression, value, marks = 2, tolerance = .005) => [method(label, expression, marks - 1), answer(label, value, 1, tolerance)];
const concept = (label, proof, pattern, marks = 1, alternative = proof) => ({
  label, marks, kind: 'concept', match: { all: [pattern], none: ['\\b(?:not|never|no)\\s+(?:an?\\s+)?(?:asset|liability|expense|income|capital|debit|credit|increase|decrease|recognise|record)\\b'] },
  fullProof: proof, alternativeProof: alternative, incorrectProof: `It is false that ${proof}`,
});
const entry = (debit, credit, value, marks = 2) => ({
  label: `Debit ${debit}; credit ${credit}`, marks, kind: 'entry',
  match: { all: [`\\b(?:debit|dr)\\s+${canonical(debit)}`, `\\b(?:credit|cr)\\s+${canonical(credit)}`] }, numbers: [{ value, tolerance: .005 }],
  fullProof: `Debit ${debit} ${value}; credit ${credit} ${value}`,
  alternativeProof: `Dr ${debit} $${value}; Cr ${credit} $${value}`,
  incorrectProof: `Credit ${debit} ${value}; debit ${credit} ${value}`,
});
const heading = (name, marks = 1) => ({
  ...concept(`${name} presentation`, `${name}\nDebit | Credit\nBalance c/d | Balance b/d`, `${canonical(name)}[\\s\\S]{0,100}(?:debit[\\s\\S]{0,30}credit|dr[\\s\\S]{0,30}cr)`, marks),
  kind: 'presentation',alternativeProof:`${name}\nDr | Cr\nBalance c/d | Balance b/d`,incorrectProof:`${name}\nAmount\nNo debit or credit columns`,
});
const section = (id, maxMarks, points) => ({ id, maxMarks, points: points.flat().map((p, i) => ({ id: `${id}-${i + 1}`, ...p })) });
const q = (year, number, sections, notes = []) => {
  const paperId = `poa-2-${year}-mj`;
  const paper = POA_HISTORICAL_PAPER2_ARCHIVE.find((p) => p.id === paperId);
  return { paperId, questionNumber: number, policyVersion: 'spark-historical-methods-v1', authority: 'spark-authored',
    sourceSha256: paper.sourceSha256, sourceCaps:sections.map(s=>({id:s.id,maxMarks:s.maxMarks})), sections, sourceNotes: [...(paper.questions.find((item) => item.number === number).sourceNotes || []), ...notes] };
};

