// Exported calculation recipes let the independent fixtures recompute answers
// from source quantities without reading the rubric's stored expected results.
export const POA_EARLY_POLICY_HELPERS = { answer, method, calc, concept, entry, heading, section, q };

// Accept an alternate reading only when the student states that reading. The
// active branch replaces the primary expected figures for all affected lines.
const alternateReading = (year, questionNumber, id, description, when, replacements, expressions = {}) => {
  const policy=POA_HISTORICAL_METHODS_EARLY.find(q=>q.paperId===`poa-2-${year}-mj`&&q.questionNumber===questionNumber);
  const branch={id,description,when:[when]};
  policy.sourceAssumptions=[...(policy.sourceAssumptions||[]),branch];
  for(const section of policy.sections)for(const point of section.points){
    if(Object.hasOwn(replacements,point.label))point.numberAlternatives=[...(point.numberAlternatives||[]),{value:replacements[point.label],when:[when],branch:id,tolerance:point.numbers?.[0]?.tolerance??.005}];
    if(expressions[point.label])point.expressions.push(expressions[point.label]);
  }
};
