// Dependent marks may follow an actual earlier claimed amount. They never infer
// an invented prior answer, and the full arithmetic relationship is recorded.
const ownFigure = (year, questionNumber, fromLabel, targetLabel, expression) => {
  const policy=POA_HISTORICAL_METHODS_EARLY.find(q=>q.paperId===`poa-2-${year}-mj`&&q.questionNumber===questionNumber);
  const point=policy.sections.flatMap(s=>s.points).find(p=>p.label===targetLabel);
  const amount='\\s*[:=]\\s*\\$?(?<value>-?[0-9][0-9,]*(?:\\.[0-9]+)?)';
  if(!point)throw new Error(`Unknown own-figure target ${year} ${questionNumber} ${targetLabel}`);
  point.ownFigure={fromLabel,fromPattern:'(?:^|\\n)\\s*'+canonical(fromLabel)+amount,expression,answerPattern:'(?:^|\\n)\\s*'+canonical(targetLabel)+'[^\\n;=]*=\\s*\\$?(?<value>-?[0-9][0-9,]*(?:\\.[0-9]+)?)'};
};
