// The cash-paid versus already-accrued reading is a convention mark, not an
// instruction to affirm two inconsistent bases at once.
{
  const policy=POA_HISTORICAL_METHODS_EARLY.find(q=>q.paperId==='poa-2-2010-mj'&&q.questionNumber===3);
  const point=policy.sections.flatMap(s=>s.points).find(p=>p.label==='Expenses convention');
  point.match.all=['6115[\\s\\S]{0,100}(?:(?:cash|paid)[\\s\\S]{0,80}(?:adjust|prepay|accrual)|already accrued|expenses incurred)'];
}
{
  const policy=POA_HISTORICAL_METHODS_EARLY.find(q=>q.paperId==='poa-2-2012-mj'&&q.questionNumber===7);
  for(const section of policy.sections)for(const point of section.points){
    if(point.label!=='Undistributed surplus')continue;
    const label=`${section.id==='a'?'First':'Second'} year undistributed surplus`;
    point.label=label;point.match.all=['(?:^|\\n)\\s*'+canonical(label)+'\\s*[:=]'];
    point.fullProof=`${label}: ${point.numbers[0].value}`;
    point.alternativeProof=`${label}: $${point.numbers[0].value}`;
    point.incorrectProof=`${label}: -999`;
  }
}
{
  const policy=POA_HISTORICAL_METHODS_EARLY.find(q=>q.paperId==='poa-2-2008-mj'&&q.questionNumber===7);
  for(const point of policy.sections.flatMap(s=>s.points)){
    if(!point.label.startsWith('Return on opening capital'))continue;
    point.label=point.label.replace('Return on opening capital','Return on capital invested');
    for(const field of ['fullProof','alternativeProof','incorrectProof'])point[field]=point[field].replaceAll('Return on opening capital','Return on capital invested');
    point.match.all=point.match.all.map(pattern=>pattern.replace(canonical('Return on opening capital'),canonical('Return on capital invested')));
  }
}
